use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.planks();
    var result = "";
    var first = true;
    var i = 0;
    while i < planks.len() {
        let plank = planks[i];
        if rules.keep(plank) {
            if first {
                first = false;
                result = rules.label(plank);
            } else {
                result = result.concat(other: ",");
                result = result.concat(other: rules.label(plank));
            }
        }
        i = i + 1;
    }
    result
}

