use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.sequence();
    var parts: List<String> = [];
    var i = 0;
    while i < signals.len() {
        let signal = match signals.get(index: i) {
            Some(s) => s,
            None => harbor.signal.Signal.Calm,
        };
        let part = match signal {
            harbor.signal.Signal.Calm => "calm",
            harbor.signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            harbor.signal.Signal.Fog(density) => "fog:".concat(other: density),
        };
        parts.push(item: part);
        i = i + 1;
    }
    parts.join(sep: ";")
}

